/// Slot `slot` of `node`, a node of `kind` (checked in safety builds).
fn @"ir.at"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot] else .nil;
}

/// The children of `node` from `slot` on.
fn @"ir.restAt"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) []const Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot..] else &.{};
}

fn @"ir.check"(node: Sexp, comptime kind: Tag, comptime what: []const u8) void {
    if (std.debug.runtime_safety and !node.isKind(kind)) {
        const actual = if (node.kind()) |k| @tagName(k) else @tagName(node);
        std.debug.panic(what ++ ": node is '{s}', not '" ++ @tagName(kind) ++ "'", .{actual});
    }
}


// =============================================================================
// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
const hasRepair = false;
const numSymbols = 190;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(_: *BaseParser, token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"newline" => 75,
        .@"indent" => 76,
        .@"outdent" => 77,
        .@"ident" => 79,
        .@"post_if" => 80,
        .@"new" => 84,
        .@"drop_stmt" => 85,
        .@"return" => 86,
        .@"break" => 87,
        .@"continue" => 88,
        .@"defer" => 89,
        .@"errdefer" => 90,
        .@"raw" => 91,
        .@"pub" => 102,
        .@"use" => 103,
        .@"fun" => 104,
        .@"sub" => 105,
        .@"lparen_call" => 109,
        .@"lbracket_index" => 111,
        .@"read_pfx" => 113,
        .@"write_pfx" => 114,
        .@"kwarg_name" => 115,
        .@"enum" => 116,
        .@"error" => 117,
        .@"struct" => 118,
        .@"type" => 119,
        .@"drop" => 120,
        .@"test" => 123,
        .@"string_dq" => 124,
        .@"string_sq" => 125,
        .@"extern" => 126,
        .@"share_pfx" => 127,
        .@"integer" => 130,
        .@"suffix_q" => 134,
        .@"suffix_bang" => 135,
        .@"catch" => 137,
        .@"bar_capture" => 138,
        .@"ternary_if" => 139,
        .@"else" => 140,
        .@"or" => 141,
        .@"and" => 142,
        .@"not" => 143,
        .@"move_pfx" => 145,
        .@"as" => 146,
        .@"if" => 147,
        .@"while" => 148,
        .@"for" => 149,
        .@"in" => 150,
        .@"match" => 151,
        .@"minus_prefix" => 154,
        .@"true" => 155,
        .@"false" => 156,
        .@"dot_lit" => 157,
        .@"bar_empty" => 158,
        .@"clone_pfx" => 159,
        .@"real" => 160,
        .@"colon" => 78,
        .@"assign" => 83,
        .@"rparen" => 107,
        .@"comma" => 108,
        .@"lparen" => 110,
        .@"rbracket" => 112,
        .@"tilde" => 128,
        .@"lbracket" => 129,
        .@"dot" => 136,
        .@"at" => 161,
        .@"lt" => 175,
        .@"gt" => 176,
        .@"bar" => 180,
        .@"caret" => 181,
        .@"ampersand" => 182,
        .@"plus" => 185,
        .@"minus" => 186,
        .@"star" => 187,
        .@"slash" => 188,
        .@"percent" => 189,
        .@"fixed_assign" => 81,
        .@"move_assign" => 82,
        .@"plus_assign" => 92,
        .@"minus_assign" => 93,
        .@"star_assign" => 94,
        .@"slash_assign" => 95,
        .@"percent_assign" => 96,
        .@"amp_assign" => 97,
        .@"bar_assign" => 98,
        .@"caret_assign" => 99,
        .@"lshift_assign" => 100,
        .@"rshift_assign" => 101,
        .@"arrow" => 106,
        .@"fat_arrow" => 152,
        .@"dotdot" => 153,
        .@"eq" => 173,
        .@"ne" => 174,
        .@"le" => 177,
        .@"ge" => 178,
        .@"nullish" => 179,
        .@"lshift" => 183,
        .@"rshift" => 184,
        else => 2, // error
    };
}

fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
    @setEvalBranchQuota(1_000_000);
    return switch (ruleId) {
        0 => self.build(&.{ .{ .tag = .@"module" } }, .tree),
        1 => blk: { var out: std.ArrayListUnmanaged(Sexp) = .empty; out.append(self.allocator(), .{ .tag = .@"module" }) catch break :blk self.oomNil(); for (pass[0].items()) |item| out.append(self.allocator(), item) catch break :blk self.oomNil(); break :blk self.finishList(&out, .tree); },
        2 => self.build(&.{ pass[0] }, .spread),
        3 => blk: { var out = self.extendList(pass[0]) catch break :blk self.oomNil(); out.append(self.allocator(), pass[2]) catch break :blk self.oomNil(); break :blk self.keepList(&out, .spread); },
        4 => pass[0],
        5 => self.build(&.{ .{ .tag = .@"block" } }, .tree),
        6 => blk: { var out: std.ArrayListUnmanaged(Sexp) = .empty; out.append(self.allocator(), .{ .tag = .@"block" }) catch break :blk self.oomNil(); for (pass[1].items()) |item| out.append(self.allocator(), item) catch break :blk self.oomNil(); break :blk self.finishList(&out, .tree); },
        7 => pass[0],
        8 => pass[0],
        9 => pass[0],
        10 => pass[0],
        11 => pass[0],
        12 => self.build(&.{ .{ .tag = .@"labeled" }, pass[1], pass[2] }, .tree),
        13 => pass[0],
        14 => self.build(&.{ .{ .tag = .@"if" }, pass[2], self.nested(self.build(&.{ .{ .tag = .@"block" }, pass[0] }, .tree), 0, 0), .nil }, .tree),
        15 => pass[0],
        16 => pass[0],
        17 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"fixed" }, pass[0], .nil, pass[2] }, .tree),
        18 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"move" }, pass[0], .nil, pass[2] }, .tree),
        19 => self.build(&.{ .{ .tag = .@"set" }, .nil, pass[0], pass[2], pass[4] }, .tree),
        20 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"fixed" }, pass[0], pass[2], pass[4] }, .tree),
        21 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"shadow" }, pass[1], .nil, pass[3] }, .tree),
        22 => self.build(&.{ .{ .tag = .@"drop" }, pass[1] }, .tree),
        23 => self.build(&.{ .{ .tag = .@"return" }, .nil }, .tree),
        24 => self.build(&.{ .{ .tag = .@"return" }, pass[1] }, .tree),
        25 => self.build(&.{ .{ .tag = .@"break" }, .nil, .nil }, .tree),
        26 => self.build(&.{ .{ .tag = .@"break" }, .nil, pass[2] }, .tree),
        27 => self.build(&.{ .{ .tag = .@"break" }, pass[1], .nil }, .tree),
        28 => self.build(&.{ .{ .tag = .@"break" }, pass[3], pass[2] }, .tree),
        29 => self.build(&.{ .{ .tag = .@"continue" }, .nil }, .tree),
        30 => self.build(&.{ .{ .tag = .@"continue" }, pass[2] }, .tree),
        31 => self.build(&.{ .{ .tag = .@"defer" }, pass[1] }, .tree),
        32 => self.build(&.{ .{ .tag = .@"defer" }, pass[1] }, .tree),
        33 => self.build(&.{ .{ .tag = .@"errdefer" }, pass[1] }, .tree),
        34 => self.build(&.{ .{ .tag = .@"errdefer" }, pass[1] }, .tree),
        35 => self.build(&.{ .{ .tag = .@"raw_block" }, pass[1] }, .tree),
